pub fn namespace_match(pattern: &[u8], value: &[u8]) -> bool {
    if is_star(pattern) {
        return true;
    }
    let pat = split(pattern, b'/');
    let val = split(value, b'/');
    segments_match(&pat, 0, &val, 0)
}

