pub fn after_failure(entries: &[FailureEntry], ip: IpAddr, now: u64) -> FailureEntry {
    let failures = match find(entries, ip) {
        Some(e) => e.failures,
        None => 0,
    };
    FailureEntry { ip, failures: failures + 1, last_failure: now }
}

