}

permission_import.stronger.code:
pub fn stronger(a: Verb, b: Verb) -> Verb {
    match (a, b) {
        (Verb::Admin, _) | (_, Verb::Admin) => Verb::Admin,
        (Verb::Write, _) | (_, Verb::Write) => Verb::Write,
        _ => Verb::Read,
    }
}

