    }
    if user == e.user {
        out.push(Acc { user, verb: stronger(e.verb, verb),
            repo_scoped: e.repo_scoped || repo_scoped,
            from_group: e.from_group || from_group });
        added = true;
    } else { out.push(e); }
    i += 1;
}

