circuit_breaker.check.code:
pub fn check(mut b: Breaker, enabled: bool, reset: u64) -> (Breaker, Option<u64>) {
    if !enabled {
        return (b, Some(0));
    }
    match b.phase {
        Phase::Closed => (b, Some(0)),
        Phase::Open => {
            let elapsed = match b.failure_age {
                Some(n) => n,
                None => u64::MAX,
            };
            if elapsed >= reset {
                b.phase = Phase::HalfOpen;
                let (b, token) = grant_probe(b);
                (b, Some(token))
            } else {
                (b, None)
            }
        }
        Phase::HalfOpen => {
            let stalled = reset > 0
                && match b.probe_age {
                    None => true,
                    Some(age) => age >= reset,
                };
            if b.in_flight && !stalled {
                (b, None)
            } else {
                let (b, token) = grant_probe(b);
                (b, Some(token))
            }
        }
    }
}

circuit_breaker.grant_probe.code:
pub fn grant_probe(mut b: Breaker) -> (Breaker, u64) {
    b.generation += 1;
    b.in_flight = true;
    b.probe_age = Some(0);
    let token = b.generation;
    (b, token)
}

