pub fn is_stale(b: &Breaker, token: u64) -> bool {
    token != 0 && token != b.generation
}

circuit_breaker.record_success.code:
pub fn record_success(mut b: Breaker, enabled: bool, token: u64) -> Breaker {
    if !enabled || is_stale(&b, token) {
        return b;
    }
    b.phase = Phase::Closed;
    b.failures = 0;
    b.in_flight = false;
    b.probe_age = None;
    b
}

circuit_breaker.record_alive.code:
pub fn record_alive(mut b: Breaker, enabled: bool, token: u64) -> Breaker {
    if !enabled || is_stale(&b, token) {
        return b;
    }
    match b.phase {
        Phase::HalfOpen => {
            b.phase = Phase::Closed;
            b.failures = 0;
            b.in_flight = false;
            b.probe_age = None;
        }
        _ => {}
    }
    b
}

circuit_breaker.record_failure.code:
pub fn record_failure(mut b: Breaker, enabled: bool, token: u64, threshold: u32) -> Breaker {
    if !enabled || is_stale(&b, token) {
        return b;
    }
    match b.phase {
        Phase::Closed => {
            b.failures += 1;
            b.failure_age = Some(0);
            if b.failures >= threshold {
                b.phase = Phase::Open;
            }
        }
        Phase::HalfOpen => {
            b.phase = Phase::Open;
            b.failure_age = Some(0);
            b.in_flight = false;
            b.probe_age = None;
        }
        Phase::Open => {
            b.failure_age = Some(0);
        }
    }
    b
}

