                        reason: reason.clone(),
                        registry: registry.to_string(),
                        package: name.to_string(),
                        version: version.map(|v| v.to_string()),
                    }
                    .into_response(),
                )
            }
        }
        Decision::Allow | Decision::Skip => None,
    }
}

